package net.officefloor.hq.app.sheet;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The ids of the sheet's children: the sheets naming it as their parent (their undated parent setting), by id. */
    @Query("select distinct s.sheet.id from SheetSetting s where s.key = 'parent' and s.value = :sheetId order by s.sheet.id")
    List<String> childrenOf(@Param("sheetId") String sheetId);

    /** The parent sheet a sheet names (its undated parent setting); empty (or a null value) when none. */
    @Query("select s.value from SheetSetting s where s.sheet.id = :sheetId and s.key = 'parent'")
    List<String> parentsOf(@Param("sheetId") String sheetId);
}
package net.officefloor.hq.app.plan;

/** A plan that cannot be added: a bad amount, date or interval, or an end before its start. */
public class InvalidPlanException extends Exception {
    public InvalidPlanException(String message) {
        super(message);
    }
}
-- A plan's amount changes: on a day (the sheet's today) its amount became the new one. The plan's amount is its
-- latest; the claims generated from then on take it, those already generated keep theirs.
CREATE TABLE plan_change (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id BIGINT NOT NULL REFERENCES plan (id),
    changed_on DATE NOT NULL,
    amount DECIMAL(19, 2) NOT NULL
);
CREATE INDEX plan_change_plan ON plan_change (plan_id, id);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A person's plan as the store holds it: an amount (two decimals), a start date, either every N days (at least 1) or
 *  a day of the month (1 to 31), the other null, an end date (not before the start), and how many claims it has made
 *  so far, its next dates: the first five plan dates after the sheet's today and on or before its end that no pause
 *  skips, and whether it is paused (a date on or after the day it was paused and before the day it was resumed is
 *  skipped, not postponed), and its amount changes, oldest first, each as <date> amount=<amount>. */
export type Plan = {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
  nextDates: string[];
  paused: boolean;
  changes: string[];
};

export const plansQueryKey = (sheetId: string) => ['sheet', sheetId, 'plans'] as const;

